-- Talent points from .talents grant. Apply to the `hotfixes` database; restart worldserver.
-- QuestV2 (hash 986198281): gives each marker quest a quest-completed bit, which is how the client learns
-- it is done. Bits 72701 onwards are unused (the client data stops at 72644).
-- TraitCurrencySource (hash 2493836603): one point of the Classic talent currency 3820 per marker quest.
-- TraitCurrency (hash 2205979106): currency 3820 with its cap (SourcedMax) raised from 51 to 300.
-- The other TraitCurrency values are the client's own.
DELETE FROM quest_v2 WHERE ID BETWEEN 9100001 AND 9100249;

DELETE FROM trait_currency_source WHERE ID BETWEEN 90001 AND 90249;

DELETE FROM trait_currency WHERE ID = 3820;

DELETE FROM hotfix_data WHERE Id BETWEEN 81000436 AND 81000934;
